3	import (
4		"errors"
5		"testing"
6		"time"
7	
8		"example.com/tally/internal/money"
9		"example.com/tally/internal/store"
10	)
11	
12	func TestRevenue(t *testing.T) {
13		st := store.New()
14		day := func(d, h int) time.Time { return time.Date(2026, 3, d, h, 0, 0, 0, time.UTC) }
15		o, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, day(1, 0))
16		c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", day(1, 0))
17		inv, _ := st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, day(1, 0))
18		pay := func(amount int64, cur money.Currency, status store.PaymentStatus, at time.Time) {
19			if _, err := st.CreatePayment(store.Payment{OrgID: o.ID, InvoiceID: inv.ID, Amount: amount, Currency: cur, Status: status}, at); err != nil {
20				t.Fatal(err)
21			}
22		}
23		pay(1000, money.USD, store.PaymentSucceeded, day(2, 9))
24		pay(500, money.USD, store.PaymentSucceeded, day(2, 15))
25		pay(700, money.EUR, store.PaymentSucceeded, day(2, 12))
26		pay(999, money.USD, store.PaymentFailed, day(2, 13))
27		pay(300, money.USD, store.PaymentSucceeded, day(4, 12))
28		pay(100, money.USD, store.PaymentSucceeded, day(6, 12)) // after the range
29		got, err := Revenue(st, o.ID, "2026-03-01", "2026-03-05")
30		if err != nil {
31			t.Fatal(err)
32		}
33		want := []DayRevenue{
34			{Date: "2026-03-02", Currency: money.EUR, Amount: 700, Payments: 1},
35			{Date: "2026-03-02", Currency: money.USD, Amount: 1500, Payments: 2},
36			{Date: "2026-03-04", Currency: money.USD, Amount: 300, Payments: 1},
37		}
38		if len(got) != len(want) {
39			t.Fatalf("Revenue = %+v", got)
40		}
41		for i := range want {
42			if got[i] != want[i] {
43				t.Fatalf("day %d = %+v, want %+v", i, got[i], want[i])
44			}
45		}
46	}
47	
48	func TestRevenueRange(t *testing.T) {
49		st := store.New()
50		for _, c := range []struct {
51			from, to string
52			want     error
53		}{
54			{"2026-03-01", "2026/03/05", ErrInvalidDate},
55			{"yesterday", "2026-03-05", ErrInvalidDate},
56			{"2026-03-05", "2026-03-01", ErrInvalidRange},
57			{"2026-01-01", "2027-01-02", ErrInvalidRange},
58		} {
59			if _, err := Revenue(st, "org_x", c.from, c.to); !errors.Is(err, c.want) {
60				t.Errorf("Revenue(%s, %s) = %v, want %v", c.from, c.to, err, c.want)
61			}
62		}
63		if got, err := Revenue(st, "org_x", "2026-01-01", "2026-12-31"); err != nil || len(got) != 0 {
64			t.Fatalf("a full year: %v, %v", got, err)
65		}
66	}
