	last, err := time.Parse(time.DateOnly, to)
	if err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: to %q", ErrInvalidDate, to)
	}
	if last.Before(start) {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: to is before from", ErrInvalidRange)
	}
	if last.Sub(start) >= MaxDays*24*time.Hour {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: at most %d days", ErrInvalidRange, MaxDays)
	}
	return start, last, nil
}

// bucketStart is the first day of the bucket that holds the calendar day d.
func bucketStart(d time.Time, group string) time.Time {
	switch group {
	case "week":
		return d.AddDate(0, 0, -((int(d.Weekday()) + 6) % 7))
	case "month":
		return time.Date(d.Year(), d.Month(), 1, 0, 0, 0, 0, time.UTC)
	}
	return d
}

// nextBucket is the first day of the bucket after the one starting on start.
func nextBucket(start time.Time, group string) time.Time {
	switch group {
	case "week":
		return start.AddDate(0, 0, 7)
	case "month":
		return start.AddDate(0, 1, 0)
	}
	return start.AddDate(0, 0, 1)
}

// Package reports computes the dashboard's reports.
package reports

import (
	"errors"
	"fmt"
	"sort"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// DayRevenue is what an organization took on one day in one currency.
type DayRevenue struct {
	Date     string         `json:"date"` // YYYY-MM-DD
	Currency money.Currency `json:"currency"`
	Amount   int64          `json:"amount"`
	Payments int            `json:"payments"`
}

// Bucket is what an organization took in one day, week or month: Start is the first day of that period (YYYY-MM-DD).
type Bucket struct {
	Start    string                   `json:"start"`
	Amounts  map[money.Currency]int64 `json:"amounts"`
	Payments int                      `json:"payments"`
}

// Report is what an organization took over a range of days, grouped into buckets in its time zone.
type Report struct {
	TimeZone string   `json:"time_zone"`
	Group    string   `json:"group"`
	Buckets  []Bucket `json:"buckets"`
}

// Errors.
var (
	ErrInvalidDate  = errors.New("invalid date")
	ErrInvalidRange = errors.New("invalid date range")
	ErrInvalidGroup = errors.New("invalid group")
)

// MaxDays is the longest range a report covers.
const MaxDays = 366

// Revenue adds up the organization's succeeded payments per day and currency, from the day from to the day to (YYYY-MM-DD,
// both included). Days are days in the organization's time zone. The result is in date order, currencies in alphabetical
// order within a day; days without payments are left out.
func Revenue(st *store.Store, orgID, from, to string) ([]DayRevenue, error) {
	_, days, err := dailyRevenue(st, orgID, from, to)
	return days, err
}

// RevenueReport groups the organization's revenue from the day from to the day to (YYYY-MM-DD, both included) into days,
// weeks (starting on Monday) or months, as group names them; an empty group means days. Each bucket is named by its first
// day and every bucket from the one holding from to the one holding to is there, also those without payments.
func RevenueReport(st *store.Store, orgID, from, to, group string) (Report, error) {
	if group == "" {
		group = "day"
	}
	if group != "day" && group != "week" && group != "month" {
		return Report{}, fmt.Errorf("%w: %q", ErrInvalidGroup, group)
	}
	tz, days, err := dailyRevenue(st, orgID, from, to)
	if err != nil {
		return Report{}, err
	}
	first, _ := time.Parse(time.DateOnly, from)
	last, _ := time.Parse(time.DateOnly, to)
	rep := Report{TimeZone: tz, Group: group, Buckets: []Bucket{}}
	index := map[string]int{}
	for b := bucketStart(first, group); !b.After(last); b = nextBucket(b, group) {
		index[b.Format(time.DateOnly)] = len(rep.Buckets)
		rep.Buckets = append(rep.Buckets, Bucket{Start: b.Format(time.DateOnly), Amounts: map[money.Currency]int64{}})
	}
	for _, d := range days {
		day, _ := time.Parse(time.DateOnly, d.Date)
		b := &rep.Buckets[index[bucketStart(day, group).Format(time.DateOnly)]]
		b.Amounts[d.Currency] += d.Amount
		b.Payments += d.Payments
	}
	return rep, nil
}

// dailyRevenue is Revenue with the time zone the days are counted in.
func dailyRevenue(st *store.Store, orgID, from, to string) (string, []DayRevenue, error) {
	start, last, err := parseRange(from, to)
	if err != nil {
		return "", nil, err
	}
	tz := "UTC"
	if o, ok := st.Org(orgID); ok && o.TimeZone != "" {
		tz = o.TimeZone
	}
	loc, err := time.LoadLocation(tz)
	if err != nil {
		return "", nil, fmt.Errorf("time zone %q: %w", tz, err)
	}
	// A day starts at its midnight in loc and ends at the next one, so a day with a daylight saving change is 23 or 25 hours long.
	begin := time.Date(start.Year(), start.Month(), start.Day(), 0, 0, 0, 0, loc)
	end := time.Date(last.Year(), last.Month(), last.Day()+1, 0, 0, 0, 0, loc)
	type key struct {
		day string
		cur money.Currency
	}
	sums := map[key]*DayRevenue{}
	for _, p := range st.Payments(orgID, "") {
		if p.Status != store.PaymentSucceeded || p.CreatedAt.Before(begin) || !p.CreatedAt.Before(end) {
			continue
		}
		k := key{p.CreatedAt.In(loc).Format(time.DateOnly), p.Currency}
		d, ok := sums[k]
		if !ok {
			d = &DayRevenue{Date: k.day, Currency: k.cur}
			sums[k] = d
		}
		d.Amount += p.Amount
		d.Payments++
	}
	out := make([]DayRevenue, 0, len(sums))
	for _, d := range sums {
		out = append(out, *d)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Date != out[j].Date {
			return out[i].Date < out[j].Date
		}
		return out[i].Currency < out[j].Currency
	})
	return tz, out, nil
}

// parseRange reads the two days of a range as calendar dates (UTC has no daylight saving time, so they count exactly).
func parseRange(from, to string) (time.Time, time.Time, error) {
	start, err := time.Parse(time.DateOnly, from)
	if err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: from %q", ErrInvalidDate, from)
	}
	last, err := time.Parse(time.DateOnly, to)
	if err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: to %q", ErrInvalidDate, to)
	}
	if last.Before(start) {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: to is before from", ErrInvalidRange)
	}
	if last.Sub(start) >= MaxDays*24*time.Hour {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: at most %d days", ErrInvalidRange, MaxDays)
	}
	return start, last, nil
}

// bucketStart is the first day of the bucket that holds the calendar day d.
func bucketStart(d time.Time, group string) time.Time {
	switch group {
	case "week":
		return d.AddDate(0, 0, -((int(d.Weekday()) + 6) % 7))
	case "month":
		return time.Date(d.Year(), d.Month(), 1, 0, 0, 0, 0, time.UTC)
	}
	return d
}

// nextBucket is the first day of the bucket after the one starting on start.
func nextBucket(start time.Time, group string) time.Time {
	switch group {
	case "week":
		return start.AddDate(0, 0, 7)
	case "month":
		return start.AddDate(0, 1, 0)
	}
	return start.AddDate(0, 0, 1)
}

