// revenueFixture is a store with an organization in tz that took 100 USD at each of the given instants.
func revenueFixture(t *testing.T, tz string, at ...time.Time) (*store.Store, string) {
	t.Helper()
	st := store.New()
	setup := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	o, err := st.CreateOrg("A", store.OrgTeam, tz, 0, setup)
	if err != nil {
		t.Fatal(err)
	}
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", setup)
	inv, _ := st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, setup)
	for _, when := range at {
		if _, err := st.CreatePayment(store.Payment{OrgID: o.ID, InvoiceID: inv.ID, Amount: 100, Currency: money.USD, Status: store.PaymentSucceeded}, when); err != nil {
			t.Fatal(err)
		}
	}
	return st, o.ID
}

// bucketCounts lists each bucket as "start=payments".
func bucketCounts(rep Report) []string {
	out := []string{}
	for _, b := range rep.Buckets {
		out = append(out, fmt.Sprintf("%s=%d", b.Start, b.Payments))
	}
	return out
}

func TestRevenueInOrgTimeZone(t *testing.T) {
	st, id := revenueFixture(t, "America/New_York",
		time.Date(2026, 3, 1, 4, 30, 0, 0, time.UTC),  // 2026-02-28 23:30 EST, before the range
		time.Date(2026, 3, 3, 3, 30, 0, 0, time.UTC),  // 2026-03-02 22:30 EST
		time.Date(2026, 3, 3, 5, 30, 0, 0, time.UTC)) // 2026-03-03 00:30 EST
	got, err := Revenue(st, id, "2026-03-02", "2026-03-03")
	if err != nil {
		t.Fatal(err)
	}
	want := []DayRevenue{
		{Date: "2026-03-02", Currency: money.USD, Amount: 100, Payments: 1},
		{Date: "2026-03-03", Currency: money.USD, Amount: 100, Payments: 1},
	}
	if len(got) != len(want) || got[0] != want[0] || got[1] != want[1] {
		t.Fatalf("Revenue = %+v, want %+v", got, want)
	}
}

func TestRevenueReportDaylightSavingDays(t *testing.T) {
	// In New York, 2026-03-08 starts at 05:00 UTC and lasts 23 hours; 2026-11-01 starts at 04:00 UTC and lasts 25 hours.
