		time.Date(2026, 3, 7, 4, 59, 59, 0, time.UTC),  // 03-06 23:59:59 EST, before the range
		time.Date(2026, 3, 7, 5, 0, 0, 0, time.UTC),    // 03-07 00:00 EST
		time.Date(2026, 3, 8, 4, 59, 59, 0, time.UTC),  // 03-07 23:59:59 EST
		time.Date(2026, 3, 8, 5, 0, 0, 0, time.UTC),    // 03-08 00:00 EST, the 23-hour day starts
		time.Date(2026, 3, 9, 3, 59, 59, 0, time.UTC),  // 03-08 23:59:59 EDT
		time.Date(2026, 3, 9, 4, 0, 0, 0, time.UTC),    // 03-09 00:00 EDT
		time.Date(2026, 3, 10, 3, 59, 59, 0, time.UTC), // 03-09 23:59:59 EDT
		time.Date(2026, 3, 10, 4, 0, 0, 0, time.UTC),   // 03-10, after the range
		time.Date(2026, 10, 31, 3, 59, 59, 0, time.UTC), // 10-31 23:59:59 EDT, before the range
		time.Date(2026, 11, 1, 4, 0, 0, 0, time.UTC),    // 11-01 00:00 EDT, the 25-hour day starts
		time.Date(2026, 11, 2, 4, 59, 59, 0, time.UTC),  // 11-01 23:59:59 EST
		time.Date(2026, 11, 2, 5, 0, 0, 0, time.UTC))    // 11-02 00:00 EST
	rep, err := RevenueReport(st, id, "2026-03-07", "2026-03-09", "")
	if err != nil {
		t.Fatal(err)
	}
	if got, want := bucketCounts(rep), []string{"2026-03-07=2", "2026-03-08=2", "2026-03-09=2"}; !slices.Equal(got, want) {
		t.Fatalf("March = %v, want %v", got, want)
	}
	rep, err = RevenueReport(st, id, "2026-10-31", "2026-11-02", "day")
	if err != nil {
		t.Fatal(err)
	}
	if got, want := bucketCounts(rep), []string{"2026-10-31=1", "2026-11-01=2", "2026-11-02=1"}; !slices.Equal(got, want) {
		t.Fatalf("November = %v, want %v", got, want)
	}
	if rep.TimeZone != "America/New_York" || rep.Group != "day" || rep.Buckets[1].Amounts[money.USD] != 200 {
		t.Fatalf("report = %+v", rep)
	}
}

func TestRevenueReportGroups(t *testing.T) {
